#include "fractal/validation/transport_validation.h"
#include "fractal/protocol_security.h"
#include "fake_tls.h"
#include <stdio.h>
#define CHECK(x) do{if(!(x)){printf("fail %s:%d: %s\n",__FILE__,__LINE__,#x);return 1;}}while(0)
static fractal_security_policy good(void){fractal_security_policy p={true,false,FRACTAL_TLS_VERSION_TLS13,FRACTAL_CIPHER_TLS_AES_256_GCM_SHA384,false,false,true,false,true};return p;}
int main(void){uint32_t i,drift=0;fractal_fake_tls tls;fractal_security_policy p=good();fractal_fake_tls_init(&tls);CHECK(fractal_fake_tls_handshake(&tls,p)==FRACTAL_SECURITY_ACCEPTED);CHECK(fractal_fake_tls_can_write_application_data(&tls));for(i=0;i<fractal_validation_scenario_count();i++){const fractal_validation_scenario*s=fractal_validation_scenario_at(i);fractal_validation_semantic_result fake,secure;fractal_validation_drift_report r;CHECK(fractal_validation_run_scenario(s,FRACTAL_VALIDATION_TRANSPORT_FAKE,&fake)==0);CHECK(fractal_validation_run_scenario(s,FRACTAL_VALIDATION_TRANSPORT_TLS13_LOOPBACK,&secure)==0);r=fractal_validation_compare(&fake,FRACTAL_VALIDATION_TRANSPORT_FAKE,&secure,FRACTAL_VALIDATION_TRANSPORT_TLS13_LOOPBACK);drift+=r.semantic_drift_count;}p=good();p.tls_version=12;CHECK(fractal_security_policy_validate(p)==FRACTAL_SECURITY_REJECT_TLS_VERSION);p=good();p.cleartext=true;CHECK(fractal_security_policy_validate(p)==FRACTAL_SECURITY_REJECT_CLEARTEXT);p=good();p.service_key_replaced_without_rotation=true;CHECK(fractal_security_policy_validate(p)==FRACTAL_SECURITY_REJECT_SERVICE_KEY_REPLACEMENT);p=good();p.zero_rtt=true;p.mutating_intent=true;CHECK(fractal_security_policy_validate(p)==FRACTAL_SECURITY_REJECT_ZERO_RTT_MUTATION);printf("secure transport parity: scenarios=%u semantic drift = %u; real TLS execution=BLOCKED_BY_OPENSSL_3_5_ABSENCE_IF_UNAVAILABLE\n",fractal_validation_scenario_count(),drift);CHECK(drift==0);return 0;}
